import React, { useState } from "react";
import all_product from '../Components/Assets/all_product.js';
import CartItem from '../Components/Cart/CartItem';

const initialCart = [
  { productId: 13, qty: 1 },
  { productId: 25, qty: 2 }
];

function Cart() {
  const [cart, setCart] = useState(initialCart);
  const cartItems = cart.map(item => {
    const product = all_product.find(p => p.id === item.productId);
    return { ...item, ...product };
  });
  const total = cartItems.reduce((sum, item) => sum + item.new_price * item.qty, 0);

  const handleRemove = (productId) => {
    setCart(cart.filter(item => item.productId !== productId));
  };

  return (
    <div className="cart-page" style={{ maxWidth: 700, margin: '40px auto', background: '#fff', borderRadius: 12, boxShadow: '0 2px 8px rgba(0,0,0,0.08)', padding: 32 }}>
      <h2 style={{ marginBottom: 24 }}>Keranjang Belanja</h2>
      {cartItems.length === 0 ? (
        <p>Keranjang belanja kosong.</p>
      ) : (
        <div className="cart-list">
          {cartItems.map(item => (
            <CartItem key={item.productId} item={item} onRemove={handleRemove} />
          ))}
        </div>
      )}
      <div style={{ textAlign: 'right', fontWeight: 'bold', fontSize: 18, margin: '32px 0 24px 0' }}>
        Total: Rp {total.toLocaleString()}
      </div>
      <button className="shop-hero-btn" style={{ float: 'right' }} onClick={() => alert('Checkout berhasil!')}>Checkout</button>
    </div>
  );
}

export default Cart;
